UPDATE employee
SET delete_flag = ${@com.uit.sociuscoremodules.shared.enums.DeleteFlagEnums@DELETED.value},
    deleted_at  = CURRENT_TIMESTAMP,
    updated_at  = CURRENT_TIMESTAMP
WHERE client_id = #{clientId}
  AND delete_flag = ${@com.uit.sociuscoremodules.shared.enums.DeleteFlagEnums@NOT_DELETED.value}
